#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        int64 K;
        cin >> n >> K;
        vector<int64> v(n);
        for (int i = 0; i < n; ++i) {
            cin >> v[i];
        }

        int ans = 1;
        int cur = 1;
        for (int i = 1; i < n; ++i) {
            int64 diff = v[i] - v[i - 1];
            if (diff < 0) diff = -diff;
            if (diff <= K) {
                ++cur;
            } else {
                cur = 1;
            }
            if (cur > ans) {
                ans = cur;
            }
        }
        cout << ans << '\n';
    }
    return 0;
}
